const lessons=[{"sentences":[{"speaker":"A","text":"Hi Mark, we need to update the guest count for our annual conference next week because twelve more people registered yesterday.","position":1,"audioStartSeconds":0,"audioEndSeconds":7.633875},{"speaker":"B","text":"That is wonderful news for our attendance rate, but it means we must change our food orders quickly.","position":2,"audioStartSeconds":7.833875,"audioEndSeconds":13.869791666666666},{"speaker":"A","text":"Should we call the catering company right now before they buy the ingredients for this weekend?","position":3,"audioStartSeconds":14.069791666666667,"audioEndSeconds":19.379833333333334},{"speaker":"B","text":"Yes, let us ring them immediately and also ask if they can provide extra vegetarian options.","position":4,"audioStartSeconds":19.579833333333333,"audioEndSeconds":25.456916666666668},{"speaker":"A","text":"I will check the updated dietary requirements list while you talk to the manager on the phone.","position":5,"audioStartSeconds":25.656916666666667,"audioEndSeconds":31.327},{"speaker":"B","text":"Great, I will also ask them to send a revised invoice by this afternoon.","position":6,"audioStartSeconds":31.527,"audioEndSeconds":36.423875},{"speaker":"A","text":"Perfect, let us meet again at noon to confirm everything is settled.","position":7,"audioStartSeconds":36.623875,"audioEndSeconds":41.22441666666667},{"speaker":"A","text":"Good morning Sarah, did you receive the final delivery of new office chairs that we ordered last Tuesday?","role":"section-start","position":8,"audioStartSeconds":46.22441666666667,"audioEndSeconds":52.31975},{"speaker":"B","text":"They arrived at the reception desk this morning, but unfortunately one box is missing the necessary metal screws.","position":9,"audioStartSeconds":52.51975,"audioEndSeconds":59.33679166666667},{"speaker":"A","text":"That is very frustrating since the team needs to assemble those desks before the clients arrive tomorrow.","position":10,"audioStartSeconds":59.536791666666666,"audioEndSeconds":65.722375},{"speaker":"B","text":"I already contacted the supplier, and they promised to send someone with the replacement parts this afternoon.","position":11,"audioStartSeconds":65.922375,"audioEndSeconds":72.37854166666666},{"speaker":"A","text":"Will they charge us an extra delivery fee for fixing their mistake so quickly?","position":12,"audioStartSeconds":72.57854166666667,"audioEndSeconds":77.34658333333333},{"speaker":"B","text":"No, because it was their error, they agreed to provide the missing parts completely free of charge.","position":13,"audioStartSeconds":77.54658333333333,"audioEndSeconds":83.67470833333333},{"speaker":"A","text":"That is a relief, so I will inform the reception staff to expect the courier around two o'clock.","position":14,"audioStartSeconds":83.87470833333333,"audioEndSeconds":90.118625}],"questions":[{"prompt":"Why do the speakers need to update their order in the first conversation?","options":["More people registered for the conference.","The catering company changed their prices.","The event location was moved to a hotel."],"answer":"A","evidenceSentence":1,"evidence":"twelve more people registered yesterday","explanation":"Speaker A states that twelve more people registered yesterday, which requires updating the guest count."},{"prompt":"What additional request does speaker B suggest making to the caterer?","options":["To deliver the food one day earlier.","To provide extra vegetarian options.","To offer a discount for large groups."],"answer":"B","evidenceSentence":4,"evidence":"ask if they can provide extra vegetarian options","explanation":"Speaker B suggests asking the caterer for extra vegetarian choices to accommodate the new guests."},{"prompt":"What action will speaker A take next during the phone call?","options":["Check the updated dietary requirements list.","Call the conference venue manager.","Pay the revised invoice online."],"answer":"A","evidenceSentence":5,"evidence":"I will check the updated dietary requirements list","explanation":"Speaker A mentions checking the dietary requirements list while speaker B speaks on the phone."},{"prompt":"What problem did Sarah discover with the new office delivery?","options":["The wrong chairs were delivered to reception.","One box is missing the necessary metal screws.","The shipment arrived two days late."],"answer":"B","evidenceSentence":9,"evidence":"one box is missing the necessary metal screws","explanation":"Sarah explains that one box is missing the essential metal screws needed for assembly."},{"prompt":"How will the supplier resolve the missing parts issue?","options":["By sending someone with replacement parts this afternoon.","By refunding the total cost of the order.","By offering a credit for future purchases."],"answer":"A","evidenceSentence":11,"evidence":"promised to send someone with the replacement parts this afternoon","explanation":"The supplier promised to send a person with the replacement parts during the afternoon."},{"prompt":"What will speaker A do after hearing about the supplier's solution?","options":["Help assemble the furniture immediately.","Cancel the rest of the office order.","Inform the reception staff about the courier."],"answer":"C","evidenceSentence":14,"evidence":"inform the reception staff to expect the courier","explanation":"Speaker A says they will inform reception to expect the courier around two o'clock."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
